<script>(function(){var b=document.getElementById('menuToggle'),n=document.getElementById('siteNavigation'),o=document.getElementById('menuOverlay');if(!b||!n||!o)return;function setOpen(open){n.classList.toggle('is-open',open);o.classList.toggle('is-open',open);document.body.classList.toggle('menu-open',open);b.setAttribute('aria-expanded',open?'true':'false');b.setAttribute('aria-label',open?'Menüyü kapat':'Menüyü aç');var openMark=b.querySelector('.menu-open-mark'),closeMark=b.querySelector('.menu-close-mark');if(openMark)openMark.hidden=open;if(closeMark)closeMark.hidden=!open}function close(){setOpen(false)}setOpen(false);b.addEventListener('click',function(){setOpen(!n.classList.contains('is-open'))});o.addEventListener('click',close);n.addEventListener('click',function(e){if(e.target.closest('a'))close()});document.addEventListener('keydown',function(e){if(e.key==='Escape')close()});window.addEventListener('resize',function(){if(window.innerWidth>760)close()})})();</script><script>(function(){document.querySelectorAll('[data-card-gallery]').forEach(function(card){var data=card.querySelector('.card-gallery-data'),image=card.querySelector('.card-gallery-image'),count=card.querySelector('.card-gallery-count');if(!data||!image)return;var images=[];try{images=JSON.parse(data.textContent||'[]')}catch(e){}var index=0;card.querySelectorAll('[data-gallery-step]').forEach(function(button){button.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();if(images.length<2)return;index=(index+Number(button.dataset.galleryStep)+images.length)%images.length;image.src=images[index];if(count)count.textContent=(index+1)+' / '+images.length})})})})();</script><script>(function(){var input=document.getElementById('homeDestination'),list=document.getElementById('homeDestinationOptions'),selected=document.getElementById('homeLocationId'),form=document.getElementById('homeSearch');if(!input||!list||!selected)return;var timer=null,items=[],active=-1,seq=0;function close(){list.hidden=true;list.innerHTML='';active=-1}function choose(item){input.value=item.label;selected.value=String(item.id);close();input.setCustomValidity('')}function render(rows){items=Array.isArray(rows)?rows:[];list.innerHTML='';active=-1;items.forEach(function(item,i){var row=document.createElement('div');row.className='location-suggestion';row.setAttribute('role','option');row.setAttribute('aria-selected','false');row.textContent=item.label;row.addEventListener('pointerdown',function(e){e.preventDefault();choose(item)});list.appendChild(row)});list.hidden=items.length===0}function search(q,id){fetch('<?= e(app_url('/locations/search')) ?>?q='+encodeURIComponent(q),{credentials:'same-origin',headers:{'Accept':'application/json'}}).then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}).then(function(rows){if(id!==seq)return;render(rows)}).catch(function(){if(id===seq)close()})}input.addEventListener('input',function(){selected.value='';input.setCustomValidity('');var q=input.value.trim(),id=++seq;clearTimeout(timer);if(!q){items=[];close();return}timer=setTimeout(function(){search(q,id)},120)});input.addEventListener('focus',function(){if(items.length&&input.value.trim())list.hidden=false});input.addEventListener('keydown',function(e){if(list.hidden||!items.length)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();active=(active+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;Array.from(list.children).forEach(function(el,i){el.classList.toggle('is-active',i===active)});list.children[active].scrollIntoView({block:'nearest'})}else if(e.key==='Enter'&&active>=0){e.preventDefault();choose(items[active])}else if(e.key==='Escape')close()});input.addEventListener('change',function(){var item=items.find(function(x){return x.label===input.value});if(item)choose(item)});input.addEventListener('blur',function(){setTimeout(function(){close()},120)});if(form)form.addEventListener('submit',function(e){if(input.value.trim()&&!selected.value){e.preventDefault();input.setCustomValidity('Lütfen açılan önerilerden bir lokasyon seçin.');input.reportValidity();input.focus()}})})();</script><script>(function(){var ci=document.getElementById('homeCheckIn'),co=document.getElementById('homeCheckOut'),ciText=document.getElementById('checkInDisplay'),coText=document.getElementById('checkOutDisplay'),panel=document.getElementById('homeCalendar'),months=document.getElementById('calendarMonths'),heading=document.getElementById('calendarHeading'),nightsLabel=document.getElementById('calendarNights'),prev=document.getElementById('calendarPrev'),next=document.getElementById('calendarNext'),done=document.getElementById('calendarDone'),clear=document.getElementById('calendarClear'),form=document.getElementById('homeSearch');if(!ci||!co||!panel||!months)return;var today=new Date();today.setHours(0,0,0,0);var view=new Date(today.getFullYear(),today.getMonth(),1),selecting='check_in';var fmt=new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',year:'numeric'}),monthFmt=new Intl.DateTimeFormat('tr-TR',{month:'long',year:'numeric'});function parse(v){if(!v)return null;var p=v.split('-');return new Date(Number(p[0]),Number(p[1])-1,Number(p[2]))}function key(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}function pretty(v){var d=parse(v);return d?fmt.format(d):'Tarih ekleyin'}function addDays(d,n){var x=new Date(d);x.setDate(x.getDate()+n);return x}function sync(){ciText.textContent=ci.value?pretty(ci.value):'Tarih ekleyin';coText.textContent=co.value?pretty(co.value):'Tarih ekleyin';var a=parse(ci.value),b=parse(co.value);if(a&&b){var count=Math.round((b-a)/86400000);nightsLabel.textContent=count+' gece';}else if(a){nightsLabel.textContent='Şimdi çıkış tarihini seçin';}else{nightsLabel.textContent='Giriş ve çıkış tarihlerini seçin';}}function monthMarkup(year,month){var first=new Date(year,month,1),offset=(first.getDay()+6)%7,total=new Date(year,month+1,0).getDate(),html='<section class="calendar-month"><h3>'+monthFmt.format(first)+'</h3><div class="calendar-weekdays"><span>Pzt</span><span>Sal</span><span>Çar</span><span>Per</span><span>Cum</span><span>Cmt</span><span>Paz</span></div><div class="calendar-days">';for(var i=0;i<offset;i++)html+='<span class="calendar-empty"></span>';for(var day=1;day<=total;day++){var d=new Date(year,month,day),v=key(d),past=d<today,selected=v===ci.value||v===co.value,inRange=ci.value&&co.value&&v>ci.value&&v<co.value;var cls='calendar-day'+(past?' is-disabled':'')+(selected?' is-selected':'')+(inRange?' is-in-range':'')+(v===ci.value?' is-start':'')+(v===co.value?' is-end':'');html+='<button type="button" class="'+cls+'" data-date="'+v+'"'+(past?' disabled':'')+' aria-label="'+fmt.format(d)+'">'+day+'</button>';}return html+'</div></section>';}function render(){var second=new Date(view.getFullYear(),view.getMonth()+1,1);heading.textContent=monthFmt.format(view)+' · '+monthFmt.format(second);months.innerHTML=monthMarkup(view.getFullYear(),view.getMonth())+monthMarkup(second.getFullYear(),second.getMonth());months.querySelectorAll('[data-date]').forEach(function(btn){btn.addEventListener('click',function(){choose(btn.dataset.date);});});prev.disabled=view.getFullYear()===today.getFullYear()&&view.getMonth()===today.getMonth();sync();}function choose(v){if(selecting==='check_in'||!ci.value||(co.value&&v<=ci.value)){ci.value=v;co.value='';selecting='check_out';}else{co.value=v;selecting='check_in';}var a=parse(ci.value);co.min=a?key(addDays(a,1)):key(addDays(today,1));sync();render();if(ci.value&&co.value){ciText.setAttribute('aria-expanded','false');coText.setAttribute('aria-expanded','false');}}function position(anchor){var r=anchor.getBoundingClientRect(),width=Math.min(680,window.innerWidth-20),left=Math.max(10,Math.min(r.left+(r.width/2)-(width/2),window.innerWidth-width-10)),top=r.bottom+10;if(top+420>window.innerHeight)top=Math.max(10,r.top-430);panel.style.left=left+'px';panel.style.top=top+'px';panel.style.width=width+'px';}function open(which){selecting=which;var chosen=which==='check_out'&&ci.value?parse(ci.value):parse(ci.value)||today;view=new Date(chosen.getFullYear(),chosen.getMonth(),1);panel.hidden=false;ciText.setAttribute('aria-expanded','true');coText.setAttribute('aria-expanded','true');position(which==='check_in'?ciText:coText);render();}function close(){panel.hidden=true;ciText.setAttribute('aria-expanded','false');coText.setAttribute('aria-expanded','false');}ciText.addEventListener('click',function(){if(panel.hidden)open('check_in');else open('check_in');});coText.addEventListener('click',function(){if(panel.hidden)open('check_out');else open('check_out');});prev.addEventListener('click',function(){view=new Date(view.getFullYear(),view.getMonth()-1,1);render();});next.addEventListener('click',function(){view=new Date(view.getFullYear(),view.getMonth()+1,1);render();});done.addEventListener('click',close);clear.addEventListener('click',function(){ci.value='';co.value='';co.min=key(addDays(today,1));selecting='check_in';sync();render();});document.addEventListener('click',function(e){if(!panel.hidden&&!panel.contains(e.target)&&!ciText.contains(e.target)&&!coText.contains(e.target))close();});document.addEventListener('keydown',function(e){if(e.key==='Escape')close();});window.addEventListener('resize',function(){if(!panel.hidden)position(selecting==='check_in'?ciText:coText);});window.addEventListener('scroll',function(){if(!panel.hidden)position(selecting==='check_in'?ciText:coText)},true);if(form)form.addEventListener('submit',function(e){if(ci.value&&co.value&&co.value<=ci.value){e.preventDefault();open('check_out');}});co.min=key(addDays(parse(ci.value)||today,1));sync();render();})();</script><script>(function(){var field=document.getElementById('guestField'),trigger=document.getElementById('guestTrigger'),panel=document.getElementById('guestPopover'),hidden=document.getElementById('guestTotal'),summary=document.getElementById('guestSummary'),done=document.getElementById('guestDone');if(!field||!trigger||!panel)return;var counts={adults:2,children:0,infants:0};function render(){Object.keys(counts).forEach(function(k){document.getElementById(k+'Count').textContent=counts[k];panel.querySelector('[data-count="'+k+'"][data-step="-1"]').disabled=counts[k]<(k==='adults'?1:0)});var total=counts.adults+counts.children+counts.infants;hidden.value=total;var parts=[];if(counts.adults)parts.push(counts.adults+' yetişkin');if(counts.children)parts.push(counts.children+' çocuk');if(counts.infants)parts.push(counts.infants+' bebek');summary.textContent=parts.join(', ')}function positionPanel(){var r=trigger.getBoundingClientRect(),w=Math.min(Math.max(r.width,280),window.innerWidth-24),left=Math.max(12,Math.min(r.left,window.innerWidth-w-12));panel.style.position='fixed';panel.style.top=Math.max(12,Math.min(r.bottom+8,window.innerHeight-250))+'px';panel.style.left=left+'px';panel.style.right='auto';panel.style.bottom='auto';panel.style.width=w+'px';panel.style.maxHeight='min(360px, calc(100vh - 24px))';panel.style.overflowY='auto';panel.style.zIndex='99999'}function open(){document.body.appendChild(panel);panel.hidden=false;positionPanel();trigger.setAttribute('aria-expanded','true')}function close(){panel.hidden=true;trigger.setAttribute('aria-expanded','false');field.appendChild(panel);panel.removeAttribute('style')}trigger.addEventListener('click',function(){if(panel.hidden)open();else close()});panel.querySelectorAll('[data-count]').forEach(function(btn){btn.addEventListener('click',function(){var k=btn.dataset.count,total=counts.adults+counts.children+counts.infants;if(btn.dataset.step==='1'&&total>=16)return;counts[k]=Math.max(k==='adults'?1:0,Math.min(16,counts[k]+Number(btn.dataset.step)));render();positionPanel()})});done.addEventListener('click',close);document.addEventListener('click',function(e){if(!field.contains(e.target)&&!panel.contains(e.target))close()});document.addEventListener('keydown',function(e){if(e.key==='Escape')close()});window.addEventListener('resize',function(){if(!panel.hidden)positionPanel()});window.addEventListener('scroll',function(){if(!panel.hidden)positionPanel()},true);render()})();</script><?php \App\Core\ThemeManager::renderPartial('partials/login-modal.php', get_defined_vars()); ?></body></html>